def create_plans(apps, schema_editor):
    Plan = apps.get_model("tenancy", "SubscriptionPlan")
    for code, name, price, order, description, modules in PLANS:
        Plan.objects.update_or_create(code=code, defaults={"name": name, "price": price, "currency": "KES", "period_days": 30,
                                                            "sort_order": order, "description": description, "enabled_modules": modules, "active": True})


def platform_owned_are_free_pro(apps, schema_editor):
    """Businesses owned by the platform administrator never pay and have every feature."""
    Plan = apps.get_model("tenancy", "SubscriptionPlan")
    Subscription = apps.get_model("tenancy", "OrganizationSubscription")
    pro = Plan.objects.get(code="PRO")
    Subscription.objects.filter(organization__owner__is_superuser=True).update(plan=pro, status="ACTIVE", complimentary=True, ends_at=None)


